UPDATE t_payment_stored_card
SET stored_card_status = 'DELETED',
    active_card_id = NULL,
    deleted_time = #{deletedTime,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP},
    version = version + 1,
    update_time = #{deletedTime,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE payment_stored_card_id = #{paymentStoredCardId}
  AND stored_card_status = 'ACTIVE'
  AND version = #{version}

